'use strict';

// Benign, synthetic, self-contained fixtures. Never evidence of a model call.
const css = `
*{box-sizing:border-box}body{margin:0;padding:16px;background:var(--background,#fcfcfb);color:var(--foreground,#161616);font:14px/1.5 var(--font-sans,system-ui)}
:root{--s1:light-dark(#2a78d6,#3987e5);--s2:light-dark(#eb6834,#d95926);--s3:light-dark(#1baf7a,#199e70)}
h2{font-size:18px;margin:0 0 12px}h3{font-size:15px;margin:16px 0 8px}button,select{font:inherit;color:inherit;background:var(--muted,#eee);border:1px solid var(--border,#777);border-radius:8px;padding:6px 12px;cursor:pointer}button:focus-visible,[tabindex]:focus-visible{outline:2px solid var(--primary,#2a78d6);outline-offset:2px}
.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:12px}.muted{color:var(--muted-foreground,#555)}svg{width:100%;height:auto;display:block}svg text{fill:var(--foreground,#161616);font:13px var(--font-sans,system-ui)}.grid{stroke:var(--border,#aaa);stroke-width:1}.plot{max-width:640px}.legend{display:flex;gap:16px;flex-wrap:wrap}.key{display:inline-block;width:16px;height:10px;margin-right:6px;background:var(--s1)}.key.b{background:var(--s2)}.key.c{background:var(--s3)}
table{border-collapse:collapse;width:100%;font-variant-numeric:tabular-nums}th,td{text-align:left;padding:8px;border-bottom:1px solid var(--border,#aaa)}.table-wrap{overflow:auto}output{display:block;margin-top:10px;min-height:24px}img{display:block;max-width:100%;height:auto;image-rendering:pixelated}details{margin-top:12px}.texture .series{stroke:var(--foreground,#161616);stroke-dasharray:4 3}@media print,(forced-colors:active){.series{stroke:CanvasText;stroke-dasharray:4 3}}`;
const boot = `document.documentElement.dataset.sampleReady='true';let clicks=0;document.getElementById('sample-action').addEventListener('click',()=>{document.documentElement.dataset.interacted=String(++clicks);});`;
function page(id, body, script = '') {
  return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>${css}</style></head><body data-sample="${id}">${body}<output id="sample-state" aria-live="polite">Ready · 待操作</output><script>${boot}${script}</script></body></html>`;
}
const button = text => `<div class="actions"><button id="sample-action" type="button">${text}</button></div>`;
const table = (heads, rows) => `<div class="table-wrap"><table><thead><tr>${heads.map(x => `<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row => `<tr>${row.map(x => `<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const sample = (id, title, height, html, expected) => Object.freeze({ id, title, height, html, expected });
function charts() {
  const bars = [48, 32, 20].map((n, i) => `<g tabindex="0" data-tip="${['代码 Code', '文档 Docs', '测试 Tests'][i]}: ${n}"><rect x="100" y="${12 + i * 42}" width="${n * 8}" height="20" rx="4" fill="var(--s1)"/><text x="8" y="${28 + i * 42}">${['Code', 'Docs', 'Tests'][i]}</text><text x="${110 + n * 8}" y="${28 + i * 42}">${n}</text></g>`).join('');
  const dots = [20, 35, 30, 50].map((n, i) => `<circle cx="${70 + i * 120}" cy="${150 - n * 2}" r="5" fill="var(--s1)" stroke="var(--background,#fcfcfb)" stroke-width="2"/>`).join('');
  let angle = -Math.PI / 2;
  const slices = [48, 32, 20].map((n, i) => {
    const end = angle + n / 100 * Math.PI * 2;
    const p = a => `${110 + 80 * Math.cos(a)},${95 + 80 * Math.sin(a)}`;
    const d = `M110,95L${p(angle)}A80,80 0 ${n > 50 ? 1 : 0},1 ${p(end)}Z`;
    angle = end;
    return `<path class="series" d="${d}" fill="var(--s${i + 1})" stroke="var(--background,#fcfcfb)" stroke-width="2"/>`;
  }).join('');
  return page('charts', `${button('显示纹理 / Texture')}<div class="plot"><h2>文件分布 · Files</h2><svg viewBox="0 0 600 156" role="img" aria-label="Horizontal bar chart, zero baseline, counts 48 32 20"><path class="grid" d="M100 6V136H510"/>${bars}<text x="98" y="152">0</text><text x="490" y="152">50 files</text></svg><h3>每周整理 · Weekly progress</h3><svg id="line" viewBox="0 0 600 180" role="img" aria-label="Line chart: week 1 20, week 2 35, week 3 30, week 4 50"><path class="grid" d="M50 25V150H470M50 100H470M50 50H470"/><text x="15" y="152">0</text><text x="8" y="52">50</text><path class="series" fill="none" stroke="var(--s1)" stroke-width="2" d="M70 110L190 80L310 90L430 50"/>${dots}<path id="crosshair" class="grid" d="M70 20V150"/>${[1,2,3,4].map((n,i)=>`<rect tabindex="0" data-week="${i}" x="${50+i*120}" y="20" width="110" height="135" fill="transparent"/><text x="${60+i*120}" y="175">W${n}</text>`).join('')}<text x="450" y="50">50</text></svg><h3>100 个文件的构成 · Composition</h3><svg viewBox="0 0 600 190" role="img" aria-label="Pie chart: Code 48%, Docs 32%, Tests 20%">${slices}<text x="250" y="50">Code 48%</text><text x="250" y="90">Docs 32%</text><text x="250" y="130">Tests 20%</text></svg><p class="legend"><span><i class="key"></i>Code</span><span><i class="key b"></i>Docs</span><span><i class="key c"></i>Tests</span></p></div><details><summary>数据表 / Data table</summary>${table(['Series / week','Count'],[['Code',48],['Docs',32],['Tests',20],['W1',20],['W2',35],['W3',30],['W4',50]])}</details>`, `
const out=document.getElementById('sample-state');document.getElementById('sample-action').addEventListener('click',()=>{document.body.classList.toggle('texture');out.textContent='Texture toggled';});
for(const mark of document.querySelectorAll('[data-tip]'))for(const event of ['pointermove','focus'])mark.addEventListener(event,()=>{out.textContent=mark.dataset.tip;});
for(const mark of document.querySelectorAll('[data-week]'))for(const event of ['pointermove','focus'])mark.addEventListener(event,()=>{const i=Number(mark.dataset.week);document.getElementById('crosshair').setAttribute('d','M'+(70+i*120)+' 20V150');out.textContent='W'+(i+1)+': '+[20,35,30,50][i]+' files';});`);
}
function getNormalSamples() {
  return [
    sample('repository-report', '仓库整理前后 / Repository cleanup', 360, page('repository-report', `<h2>仓库整理 · Synthetic fixture</h2>${button('查看整理后 / After')}${table(['指标 / Metric','Before','After'],[['松散文件 / Loose files',48,12],['重复文档 / Duplicate docs',8,2],['可定位测试 / Indexed tests',20,36]])}<p id="report-phase">Before: 48 loose files</p>`, `document.getElementById('sample-action').addEventListener('click',()=>{document.getElementById('report-phase').textContent='After: 12 loose files';document.getElementById('sample-state').textContent='After: 12';});`), 'After: 12'),
    sample('charts', 'Bar / line / pie', 640, charts(), 'Texture toggled'),
    sample('architecture', 'SVG 架构 / Architecture', 360, page('architecture', `<h2>可视化回复路径 · Architecture</h2>${button('突出发布路径 / Highlight')}<svg viewBox="0 0 600 210" role="img" aria-label="Pi RPC to html_render to Store to Electron timeline"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="currentColor"/></marker></defs>${['Pi RPC','html_render','Store','Timeline'].map((x,i)=>`<rect x="${10+i*150}" y="65" width="130" height="64" rx="8" fill="var(--muted,#eee)" stroke="currentColor"/><text x="${22+i*150}" y="103">${x}</text>`).join('')}<path id="route" d="M140 97H158M290 97H308M440 97H458" fill="none" stroke="currentColor" stroke-width="2" marker-end="url(#arrow)"/></svg>`, `document.getElementById('sample-action').addEventListener('click',()=>{document.getElementById('route').setAttribute('stroke-width','4');document.getElementById('sample-state').textContent='Route highlighted';});`), 'Route highlighted'),
    sample('filter-panel', '筛选按钮 / Filter panel', 360, page('filter-panel', `<h2>任务清单 / Tasks</h2>${button('只看测试 / Tests only')}<ul id="items"><li>Code · 整理模块</li><li data-test>Tests · 回归用例</li><li>Docs · 更新索引</li></ul>`, `document.getElementById('sample-action').addEventListener('click',()=>{for(const li of document.querySelectorAll('#items li'))li.hidden=!li.hasAttribute('data-test');document.getElementById('sample-state').textContent='1 matching task';});`), '1 matching task'),
    sample('long-table', '长表动态展开 / Expand table', 320, page('long-table', `<h2>文件索引 / File index</h2>${button('展开 180 行 / Expand 180 rows')}<div id="rows">Collapsed · 已收起</div>`, `let expanded=false;document.getElementById('sample-action').addEventListener('click',()=>{expanded=!expanded;const box=document.getElementById('rows');box.replaceChildren();if(expanded){const t=document.createElement('table');const caption=t.createCaption();caption.textContent='180 synthetic rows';const head=t.createTHead().insertRow();for(const label of ['#','文件 / File','Bytes']){const th=document.createElement('th');th.textContent=label;head.append(th);}const b=t.createTBody();for(let i=1;i<=180;i++){const row=b.insertRow();for(const v of [i,'fixture-'+i+'.txt',i*16])row.insertCell().textContent=String(v);}box.append(t);}else box.textContent='Collapsed';document.getElementById('sample-state').textContent=expanded?'180 rows expanded':'Collapsed';});`), '180 rows expanded'),
    sample('raster-image', '内嵌 PNG / Embedded raster', 320, page('raster-image', `<h2>内嵌像素图 / Embedded PNG</h2>${button('切换尺寸 / Resize')}<img id="raster" width="128" height="128" alt="Synthetic two by two color grid" src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAYAAABytg0kAAAAFElEQVQImWP4z8Dwn4GBgYGJAQoAHgQCAZ7cAqIAAAAASUVORK5CYII=">`, `document.getElementById('sample-action').addEventListener('click',()=>{document.getElementById('raster').style.width='256px';document.getElementById('sample-state').textContent='Image resized';});`), 'Image resized'),
  ];
}
function normalSample(id) {
  const result = getNormalSamples().find(row => row.id === id);
  if (!result) throw Error('unknown_normal_sample');
  return result;
}
module.exports = { getNormalSamples, normalSample };
